using System;
using System.IO;
using System.Linq;
using Touchfish;
public static partial class RuleTests {
 static void Heroes(){
  var g=MatchFixture("WARLOCK");g.Players[0].Health=3;g.Players[0].Armor=5;g.Players[0].Frozen=true;g.Players[0].TempAttack=4;g.Players[0].PowerUsed=true;g.EquipRaw(0,"GAME_DAGGER",1,2,false);int deck=g.Players[0].Deck.Count;int other=Hand(g,"CS2_182");Check(g.Play(0,Hand(g,"EX1_323")).Success,"Jaraxxus replaces hero through played battlecry");var p=g.Players[0];Check(p.HeroFormId==HeroReplacementRules.JaraxxusId&&p.Health==15&&g.HeroHealthLimit(0)==15&&p.Armor==0&&!p.Frozen&&p.TempAttack==0,"Replacement clears old hero state and sets fifteen maximum health");Check(p.Board.Count==0&&p.ClassId=="WARLOCK"&&p.Deck.Count==deck&&p.Hand.Single().Id==other,"Replacement removes body without changing class deck or remaining hand");Check(p.WeaponAttack==3&&p.WeaponDurability==8&&p.WeaponId=="GAME_BLOOD_FURY"&&g.Graveyard.Count(e=>e.Reason==GraveyardReason.WeaponReplaced)==1,"Blood Fury replaces old weapon through existing weapon transaction");Check(!p.PowerUsed&&g.PowerLabel(0)=="地狱火！"&&!g.PowerNeedsTarget(0),"Replacement refreshes Inferno and target behavior");Check(g.Graveyard.All(e=>e.Reason!=GraveyardReason.MinionDied),"Hero substitution creates no fake minion death");g.Heal(new MatchTarget(0),99);Check(p.Health==15,"Jaraxxus healing capped at fifteen");p.Mana=10;Check(g.HeroPower(0).Success&&p.Mana==8&&p.Board.Single().CardId=="VAN_EX1_tk34"&&p.Board.Single().Health==6&&g.AttackValue(p.Board.Single())==6,"Inferno summons unmodified six-six demon for two mana");Check(!g.HeroPower(0).Success&&p.Mana==8,"Inferno only once per turn");
  var view=LanProtocol.ReadView(catalog,LanProtocol.Copy(LanProtocol.View(g,1,"hero",1)));Check(view.Players[0].HeroFormId==p.HeroFormId&&view.HeroHealthLimit(0)==15&&view.PowerLabel(0)==g.PowerLabel(0)&&view.HeroRace(0)=="DEMON","Explicit public hero state survives serialization");Check(g.VisualEvents.Count(e=>e.Kind=="hero-speech")==1&&g.VisualEvents.Single(e=>e.Kind=="hero-speech").CardName=="我是加拉克苏斯，燃烧军团的艾瑞达之王","Exact entrance line is one structured public event");
  g=MatchFixture("WARLOCK");var body=g.Summon(0,"VAN_EX1_323");Check(g.Players[0].HeroFormId==null&&g.Players[0].Health==30&&body.Health==15&&g.Players[0].WeaponId==null,"Summoned Jaraxxus remains minion and does not replace hero");
  g=MatchFixture("WARLOCK");for(int n=0;n<7;n++)g.Summon(0,"VAN_CS2_231");int card=Hand(g,"EX1_323");Check(!g.Play(0,card).Success&&g.Players[0].Mana==10&&g.Players[0].HeroFormId==null,"Full board rejects nine-mana minion atomically");
  g=MatchFixture("WARLOCK");g.ReplaceHero(0,HeroReplacementRules.JaraxxusId);for(int n=0;n<7;n++)g.Summon(0,"VAN_CS2_231");Check(!g.HeroPower(0).Success&&g.Players[0].Mana==10&&!g.Players[0].PowerUsed,"Full board Inferno does not consume mana or ability");
  g=MatchFixture("WARLOCK");g.ReplaceHero(0,HeroReplacementRules.JaraxxusId);g.EquipRaw(0,"GAME_BLOOD_FURY",3,8,false);Check(g.Attack(0,0,new MatchTarget(1)).Success&&g.Players[1].Health==27&&g.Players[0].WeaponDurability==7,"Blood Fury attacks through standard weapon slot rules");g.Players[0].Frozen=true;Check(!g.Attack(0,0,new MatchTarget(1)).Success,"Replacement hero still obeys subsequent freeze");
  g=MatchFixture("WARLOCK");g.ReplaceHero(0,HeroReplacementRules.JaraxxusId);g.HeroPower(0);g.Players[0].Mana=10;g.Play(0,Hand(g,"EX1_625"));Check(g.Players[0].HeroFormId==HeroReplacementRules.JaraxxusId&&g.PowerNeedsTarget(0)&&g.PowerLabel(0)=="心灵尖刺","Power can change independently of hero form");
  g=MatchFixture("WARLOCK");g.ReplaceHero(1,HeroReplacementRules.JaraxxusId);g.Players[0].Health=20;Check(g.Play(0,Hand(g,"NEW1_003"),new MatchTarget(1)).Success&&g.Finished&&g.Winner==0&&g.Players[0].Health==25,"Classic Sacrificial Pact can destroy enemy demon hero");
  g=MatchFixture("WARLOCK");g.ReplaceHero(0,HeroReplacementRules.JaraxxusId);g.Play(0,Hand(g,"NEW1_003"),new MatchTarget(0));Check(g.Finished&&g.Winner==1&&g.Players[0].Health==0,"Self Pact destroys hero without healing resurrection");
  g=MatchFixture("PALADIN");g.EquipRaw(0,"VAN_EX1_366",1,5,false);card=Hand(g,"EX1_323");g.Players[0].Hand.Single(h=>h.Id==card).Generated=true;g.Play(0,card);Check(g.Players[0].Health==15&&g.Graveyard.All(e=>e.Reason!=GraveyardReason.WeaponDestroyed),"Played Jaraxxus bypasses Sword summon trigger and retains fifteen health");
  g=MatchFixture("WARLOCK");g.Players[0].HeroAttacks=1;g.Play(0,Hand(g,"EX1_323"));Check(!g.Attack(0,0,new MatchTarget(1)).Success&&g.Players[0].WeaponDurability==8,"Hero replacement preserves already-used attack count");
  HeroReplacementRules.RegisterAbility(new HeroAbilityDefinition("test:ability@1","自定义技能",1,"ENEMY_CHARACTER",(game,seat,target)=>game.Damage(target,2)));
  HeroReplacementRules.RegisterHero(new HeroReplacementDefinition("test:hero@1","测试英雄",20,"test:ability@1",preserveArmor:true,preserveHealth:true,armorGain:3));g=MatchFixture();g.Players[0].Health=12;g.Players[0].Armor=4;g.ReplaceHero(0,"test:hero@1");Check(g.Players[0].Health==12&&g.Players[0].Armor==7&&g.HeroHealthLimit(0)==30&&g.HeroPowerCost(0)==1,"Extension definition supports preserving health armor and independent power cost");Check(!g.HeroPower(0).Success&&g.Players[0].Mana==10&&!g.Players[0].PowerUsed,"Custom power validates required target before spending");Check(g.HeroPower(0,new MatchTarget(1)).Success&&g.Players[0].Mana==9&&g.Players[1].Health==28,"Registered custom hero power resolves through common input contract");
  var all=catalog.Deckable(catalog.Pool("classic-2014"));Check(all.Where(c=>c.CardClass=="WARLOCK").All(matchRules.Supports),"Warlock all twenty-five supported");var folder=Path.Combine(Environment.CurrentDirectory,"previews");Directory.CreateDirectory(folder);JsonData.Write(Path.Combine(folder,"match-rule-coverage.json"),new{SupportedCards=all.Count(matchRules.Supports),TotalCards=all.Count,Cards=all.Select(c=>new{Id=c.Id,Name=c.Name,Supported=matchRules.Supports(c)}).ToArray(),Scope="All classic cards; Warlock 25/25 and hero replacement"});
